  def('cuisine', '🍳 Cuisiner seule', function (s) { var r = s._choice || 'pates', bonus = { pates: 45, omelette: 40, crepes: 35, patisserie: 30 }[r] || 40; LL.add({ faim: bonus, fun: 8 }); LL.xp('cuisine', r === 'patisserie' ? 8 : 5); if (r === 'patisserie') { LL.giveItem('cupcake', 2); LL.toast('🧁 +2 cupcakes dans l\'inventaire'); } LL.log('🍳 Lyham a cuisiné : ' + ({ pates: 'des pâtes', omelette: 'une omelette', crepes: 'des crêpes', patisserie: 'des cupcakes' }[r])); }, function (s) { return papaHere('cuisine') ? 'Papa est aux fourneaux ! Choisis « Aider papa » 👨‍🍳' : true; }, { id: 'cuisine_cuisiner', dur: 40, ask: 'recette', custom: 'cook' });
  def('cuisine', '👨‍🍳 Aider papa à cuisiner', function () { LL.add({ faim: 50, fun: 10, social: 10 }); LL.xp('cuisine', 6); LL.rel('casimir', LL.once('rel_casimir_aide') ? 3 : 0); }, function () { return papaHere('cuisine') ? true : 'Papa ne cuisine pas en ce moment (vers 12 h et 18 h 30).'; }, { id: 'cuisine_aider', dur: 45, custom: 'helpPapa' });
