    cook: function (done) { var r = LL.S._choice || 'pates', M2 = LL.M; LL.seq([
      { walk: [290, 488] }, { anim: A('takePan', 0.8, { arm: 'up', dir: -1, snd: 'casserole', end: function () { L().hold = 'pan'; } , keepPose: true }) },
      { fn: function () { L().hold = 'pan'; } }, { walk: [372, 488] },
      { anim: A('putPan', 0.6, { arm: 'out', dir: 1, hold: 'pan', snd: 'casserole', end: function () { M2.panOnStove = true; M2.stoveOn = true; } }) },
      { anim: A('cook', 3.2, { arm: 'stir', dir: 1, expr: 'concentre', snd: 'gresille', loopSnd: 'gresille', sndRate: 0.6, p: ['~', '~', r === 'crepes' ? '🥞' : r === 'omelette' ? '🍳' : r === 'patisserie' ? '🧁' : '🍝'], px: 30, py: 135, po: { vy: 40, life: 1.6 }, every: 0.2, overlay: function (g) { K().pan(g, 335, 340, 1.1); if (r === 'crepes') { g.fillStyle = '#f2c46d'; g.beginPath(); g.ellipse(335, 337, 12, 3.5, 0, 0, 6.283); g.fill(); } else if (r === 'omelette') { g.fillStyle = '#ffd43b'; g.beginPath(); g.ellipse(335, 337, 12, 3.5, 0, 0, 6.283); g.fill(); } else { g.fillStyle = '#ffe8a3'; for (var i = 0; i < 5; i++) { g.beginPath(); g.arc(328 + i * 4, 337, 2, 0, 6.283); g.fill(); } } } }) },
      { fn: function () { M2.stoveOn = false; M2.panOnStove = false; L().hold = 'plate'; LL.son('ding'); } }, { walk: [100, 570] },
      { anim: A('eat', 2.2, { pose: 'sit', at: [100, 570], dir: 1, hold: 'plate', arm: 'out', p: ['😋', '💕'], snd: 'cuillere', loopSnd: 'cuillere', sndRate: 0.8 }) }], done); },
    helpPapa: function (done) { var pa = LL.M.npcs.filter(function (n) { return n.id === 'casimir'; })[0]; if (pa) { pa.busy = true; pa.tx = 330; } var tasks = [['casimir', 'Coupe les tomates en rondelles, ma grande 🍅'], ['casimir', 'Maintenant, remue la sauce doucement…'], ['casimir', 'Une pincée de sel… pas tout le pot ! 😂'], ['casimir', 'Parfait ! Tu deviens une vraie cheffe.']];
      LL.seq([{ walk: [420, 490] }, { fn: function () { LL.M.stoveOn = true; } }, { anim: A('help1', 2, { arm: 'stir', hold: 'brush', dir: -1, start: function () { LL.M.say(tasks[0][0], tasks[0][1], 2); }, snd: 'cuillere' }) }, { anim: A('help2', 2.2, { arm: 'stir', dir: -1, expr: 'concentre', snd: 'gresille', p: ['~', '~'], px: -40, py: 135, every: 0.2, start: function () { LL.M.say('casimir', tasks[1][1], 2); } }) }, { anim: A('help3', 1.8, { arm: 'out', dir: -1, expr: 'rire', start: function () { LL.M.say('casimir', tasks[2][1], 2); LL.M.say('lyham', 'Oups ! 😅', 1.5); } }) }, { fn: function () { LL.M.stoveOn = false; LL.M.say('casimir', tasks[3][1], 2); } }, { walk: [100, 570] }, { anim: A('eat', 2, { pose: 'sit', at: [100, 570], dir: 1, hold: 'plate', arm: 'out', p: ['😋', '👨‍🍳'] }) }, { fn: function () { if (pa) pa.busy = false; } }], done); },
    fridge: function (done) { LL.seq([{ walk: [820, 500] }, { anim: A('openFridge', 1, { arm: 'out', dir: 1, snd: 'frigo', start: function () { LL.M.fridgeOpen = true; } }) }, { anim: A('takeYaourt', 0.8, { arm: 'out', dir: 1, hold: 'yaourt', end: function () { LL.M.fridgeOpen = false; LL.son('porte'); } }) }, { anim: A('eatYaourt', 1.6, { hold: 'yaourt', arm: 'out', dir: -1, p: ['😋'] }) }], done); },
    football: function (done) { var b = LL.M.ball; b.on = true; b.kind = 'foot'; b.x = L().x + 60; b.y = 545; b.z = 0; b.vx = 0; b.vy = 0; b.vz = 0; LL.M.npcs.forEach(function (n) { if (/cataleya|elynn|noah|daryl/.test(n.id)) { n.player = true; n.busy = true; } }); LL.M.passes = 0; LL.M.setTitle('⚽ Partie de ballon'); if (LL.M.moka.here) { LL.M.moka.state = 'chase'; LL.M.moka.timer = 6; }
      LL.seq([{ anim: { type: 'football', dur: 6, step: function (dt) { var l = L(); if (!l.moving) LL.M.walkTo(LL.clamp(b.x - 30 * Math.sign(b.vx || 1), 60, 900), LL.clamp(b.y, 470, 590)); } } }, { fn: function () { b.on = false; L().moving = false; LL.M.npcs.forEach(function (n) { n.player = false; n.busy = false; }); if (LL.M.passes > 1) LL.toast('⚽ ' + LL.M.passes + ' passes réussies !'); } }], done); },
