    knock: function (done) { var here = LL.presence('bureau').indexOf('casimir') >= 0; LL.seq([{ walk: [140, 520] }, { anim: A('knock', 1.2, { arm: 'out', dir: -1, snd: 'toc' }) }, { fn: function () { if (!here) LL.M.say('lyham', 'Papa n\'est pas là… 🤔', 2); else if (LL.papaEnVisio()) { LL.M.say('casimir', 'Chut, je suis en réunion ! 🤫', 2.4); LL.toast('Chut… papa est en visio dans son bureau, reviens à sa pause !'); } else LL.M.say('casimir', LL.papaAuBureau() ? 'Entre ma grande ! Deux minutes, hein 😉' : 'Entre ma grande !', 2.2); } }, { wait: 1.6 }], done); },
    coffee: function (done) { LL.once('cafe'); LL.seq([{ fn: function () { L().hold = 'mug'; } }, { walk: [500, 510] }, { anim: A('giveCoffee', 1.4, { hold: 'mug', arm: 'out', dir: -1, p: ['☕', '💕'] }) }, { fn: function () { LL.M.say('casimir', ['Merci ma chérie, tu me sauves la vie ☕', 'Un café livré par la meilleure fille du monde !', 'Ah, parfait, j\'ai une réunion dans 5 minutes !'][LL.S.day % 3], 2.2); } }, { wait: 1.6 }], done); },
    showResult: function (done) { LL.once('montrer'); LL.seq([{ walk: [500, 510] }, { anim: A('show', 1.6, { hold: 'letter', arm: 'up', dir: -1, expr: 'joie', p: ['🏆', '⭐'] }) }, { fn: function () { LL.M.say('casimir', ['Bravo ma grande ! Je suis fier de toi ! 🏆', 'Waouh ! Ça mérite des crêpes artistiques ce soir 🥞', 'Tu vois que le travail paie ! Champion… euh, championne !'][LL.S.day % 3], 2.6); } }, { wait: 2 }], done); },
    papaHelp: function (done) { LL.seq([{ walk: [500, 510] }, { anim: A('studyPapa', 3, { pose: 'sit', at: [520, 520], dir: -1, hold: 'book', arm: 'read', expr: 'concentre', p: ['💡', '📐'], start: function () { LL.M.say('casimir', ['Regarde : on isole x d\'abord, comme un détective 🔍', 'Fais un schéma, ça aide toujours.', 'Reformule la consigne avec tes mots, et ça devient clair.'][LL.S.day % 3], 3); } }) }], done); },
    hugPapa: function (done) { var pa = LL.M.npcs.filter(function (n) { return n.id === 'casimir'; })[0]; LL.seq([{ walk: [(pa ? pa.x : 420) + 40, 505] }, { anim: A('hug', 1.6, { arm: 'hug', dir: -1, expr: 'joie', p: ['💕', '🤗'], start: function () { if (pa) { pa.busy = true; pa.arm = 'hug'; } LL.M.say('casimir', 'Oh, un câlin surprise ! 🤗', 2); }, end: function () { if (pa) { pa.busy = false; pa.arm = null; } } }) }], done); },
    danceClass: function (done) { var npcs = LL.M.npcs; LL.S.outfit = 'danse'; if (LL.S.outfits.indexOf('danse') < 0) LL.S.outfits.push('danse'); LL.seq([{ walk: [480, 540] }, { fn: function () { LL.M.say('lopez', 'Et… 5, 6, 7, 8 ! On y va les filles !', 2.2); LL.musique('dance'); npcs.forEach(function (n) { if (n.id === 'cataleya' || n.id === 'elynn') { n.busy = true; n.dance = 0; n.tx = n.id === 'cataleya' ? 330 : 630; } }); } }, { anim: A('danceClass', 4, { dance: 1, expr: 'joie', p: ['💃', '✨', '♪'], step: function (dt) { npcs.forEach(function (n) { if (n.dance != null) n.dance += dt * 4; }); } }) }, { fn: function () { LL.stopMusique(); LL.son('applause'); LL.M.say('lopez', ['Magnifique, Lyham ! Tes bras sont plus souples.', 'Bien ! Pensez à respirer pendant le tour.', 'Superbe synchro, le trio ! 👏'][LL.S.day % 3], 2.4); npcs.forEach(function (n) { n.busy = false; n.dance = null; }); } }, { wait: 1.6 }], done); }
